python3 << 'EOF'
import re

# Let me look at the raw content of TSO-2 for each year
for year in [1978, 1979, 1980, 1981, 1982]:
    filename = f'/app/resources/treasury_bulletin_{year}_05.txt'

    with open(filename, 'r') as f:
        content = f.read()

    in_tso2 = False
    found_header = False
    print(f"\n=== {year} ===")
    for i, line in enumerate(content.split('\n')):
        if 'Table TSO-2' in line:
            in_tso2 = True
        if in_tso2 and 'By type security:' in line:
            found_header = True
        if in_tso2 and found_header and 'Treasury' in line:
            print(line[:150])
            if '---' in line:
                break
EOF
